import { test, expect } from '@playwright/test';

test.describe('Table Row Selection Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the table page
    await page.goto('http://localhost:3000/table');

    // Wait for the table to be visible
    await page.getByRole('table').waitFor({ state: 'visible' });
  });

  test('should highlight a single selected row in a different colour', async ({ page }) => {
    // Get the first row in the table
    const firstRow = page.getByRole('row').nth(1); // nth(0) is header

    // Click on the first row to select it
    await firstRow.click();

    // Verify the row is selected by checking for a selected class or style
    const selectedClass = await firstRow.getAttribute('class');
    expect(selectedClass).toContain('selected');

    // Verify the background color has changed
    const backgroundColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    // The background color should be different from unselected rows
    expect(backgroundColor).not.toBe('rgba(0, 0, 0, 0)');
  });

  test('should highlight multiple selected rows with different colour', async ({ page }) => {
    // Get multiple rows
    const firstRow = page.getByRole('row').nth(1);
    const secondRow = page.getByRole('row').nth(2);
    const thirdRow = page.getByRole('row').nth(3);

    // Select first row
    await firstRow.click();

    // Hold Ctrl and click second row to multi-select
    await secondRow.click({ modifiers: ['Control'] });

    // Hold Ctrl and click third row to multi-select
    await thirdRow.click({ modifiers: ['Control'] });

    // Verify all three rows have the selected class
    const firstRowClass = await firstRow.getAttribute('class');
    const secondRowClass = await secondRow.getAttribute('class');
    const thirdRowClass = await thirdRow.getAttribute('class');

    expect(firstRowClass).toContain('selected');
    expect(secondRowClass).toContain('selected');
    expect(thirdRowClass).toContain('selected');

    // Verify they all have the same highlight color
    const firstRowBgColor = await firstRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const secondRowBgColor = await secondRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const thirdRowBgColor = await thirdRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(firstRowBgColor).toBe(secondRowBgColor);
    expect(secondRowBgColor).toBe(thirdRowBgColor);
  });

  test('should remove highlight when deselecting a row', async ({ page }) => {
    // Get a row
    const firstRow = page.getByRole('row').nth(1);

    // Select the row
    await firstRow.click();

    // Verify it's selected
    let selectedClass = await firstRow.getAttribute('class');
    expect(selectedClass).toContain('selected');

    // Click again to deselect
    await firstRow.click();

    // Verify the selected class is removed
    selectedClass = await firstRow.getAttribute('class');
    expect(selectedClass).not.toContain('selected');
  });

  test('should maintain highlight colour consistency across different row types', async ({ page }) => {
    // Get rows from different positions
    const firstDataRow = page.getByRole('row').nth(1);
    const middleDataRow = page.getByRole('row').nth(5);
    const lastDataRow = page.getByRole('row').nth(10);

    // Select all three rows
    await firstDataRow.click();
    await middleDataRow.click({ modifiers: ['Control'] });
    await lastDataRow.click({ modifiers: ['Control'] });

    // Get the background colors
    const firstRowColor = await firstDataRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const middleRowColor = await middleDataRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const lastRowColor = await lastDataRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    // All selected rows should have the same highlight color
    expect(firstRowColor).toBe(middleRowColor);
    expect(middleRowColor).toBe(lastRowColor);
  });

  test('should visually distinguish selected rows from unselected rows', async ({ page }) => {
    // Get two rows
    const selectedRow = page.getByRole('row').nth(1);
    const unselectedRow = page.getByRole('row').nth(2);

    // Select only the first row
    await selectedRow.click();

    // Get background colors
    const selectedBgColor = await selectedRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    const unselectedBgColor = await unselectedRow.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    // The colors should be different
    expect(selectedBgColor).not.toBe(unselectedBgColor);

    // Verify the selected row has a distinct visual indicator
    const selectedHasClass = await selectedRow.evaluate((el) => {
      return el.classList.contains('selected');
    });

    const unselectedHasClass = await unselectedRow.evaluate((el) => {
      return el.classList.contains('selected');
    });

    expect(selectedHasClass).toBe(true);
    expect(unselectedHasClass).toBe(false);
  });
});
